def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    emit(out, "Start from the input; look for objects that enclose background holes.")
    hole = np.zeros_like(g, dtype=bool)
    for comp in components(g == bg):
        if not any(y == 0 or x == 0 or y == H - 1 or x == W - 1 for y, x in comp):
            for y, x in comp:
                hole[y, x] = True
    for o in objects(g, bg=bg):
        encl = False
        for y, x in o["cells"]:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W and hole[ny, nx]:
                    encl = True
        if encl:
            for y, x in o["cells"]:
                out[y, x] = 8
            emit(out, f"Object at box {o['box']} encloses a hole, so recolour it to 8.")
    emit(out, "Final grid: only closed shapes are recoloured to 8.")
    return out
